// x 为真/假, 2*i 表示假, 2*i+1 表示真
// 若 x 为真则 y 为假: add(2*x+1, 2*y); add(2*y+1, 2*x);
void tarjan(int u) { /* 同 SCC 模板 */ }
// 判定
for (int i = 0; i < n; i++)
    if (scc[2*i] == scc[2*i+1]) puts("No");
// 选择
val[i] = (scc[2*i] > scc[2*i+1]);
