【主要应用】网络流建模、二分图匹配、最小割、最大权闭合子图、星际转移。
【应用方式】Dinic 多路增广 + 当前弧优化；ISAP 或 HLPP 处理大规模数据；建图时拆点、分层、源汇连接。
【模板代码】
```cpp
struct Edge { int to, nxt, cap; } e[M];
int head[N], ecnt = 1, dep[N], cur[N];
void add(int u, int v, int c) {
    e[++ecnt] = {v, head[u], c}; head[u] = ecnt;
    e[++ecnt] = {u, head[v], 0}; head[v] = ecnt;
}
bool bfs(int s, int t) {
    memset(dep, 0, sizeof(dep));
    queue<int> q; q.push(s); dep[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i; i = e[i].nxt) {
            int v = e[i].to;
            if (e[i].cap && !dep[v]) dep[v] = dep[u] + 1, q.push(v);
        }
    }
    return dep[t];
}
int dfs(int u, int t, int f) {
    if (u == t) return f;
    int flow = 0;
    for (int &i = cur[u]; i; i = e[i].nxt) {
        int v = e[i].to;
        if (e[i].cap && dep[v] == dep[u] + 1) {
            int d = dfs(v, t, min(f, e[i].cap));
            if (d) {
                e[i].cap -= d; e[i^1].cap += d;
                f -= d; flow += d;
                if (!f) break;
            }
        }
    }
    return flow;
}
int dinic(int s, int t) {
    int flow = 0;
    while (bfs(s, t)) {
        memcpy(cur, head, sizeof(head));
        flow += dfs(s, t, INF);
    }
    return flow;
}
```

