【主要应用】带权匹配、运输问题、修车、美食节、网络扩容、航空路线。
【应用方式】在最大流基础上，每条边增加单位费用；用 SPFA 或 Dijkstra（势能）找最小费用增广路；也可用 zkw 费用流。
【模板代码】
```cpp
struct Edge { int to, nxt, cap, cost; } e[M];
int head[N], ecnt = 1, dis[N], vis[N], pre[N];
void add(int u, int v, int cap, int cost) {
    e[++ecnt] = {v, head[u], cap, cost}; head[u] = ecnt;
    e[++ecnt] = {u, head[v], 0, -cost}; head[v] = ecnt;
}
bool spfa(int s, int t) {
    memset(dis, 0x3f, sizeof(dis));
    memset(vis, 0, sizeof(vis));
    queue<int> q; q.push(s); dis[s] = 0; vis[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop(); vis[u] = 0;
        for (int i = head[u]; i; i = e[i].nxt) {
            int v = e[i].to;
            if (e[i].cap && dis[v] > dis[u] + e[i].cost) {
                dis[v] = dis[u] + e[i].cost;
                pre[v] = i;
                if (!vis[v]) vis[v] = 1, q.push(v);
            }
        }
    }
    return dis[t] != INF;
}
int mcmf(int s, int t) {
    int flow = 0, cost = 0;
    while (spfa(s, t)) {
        int f = INF;
        for (int i = t; i != s; i = e[pre[i]^1].to)
            f = min(f, e[pre[i]].cap);
        for (int i = t; i != s; i = e[pre[i]^1].to) {
            e[pre[i]].cap -= f;
            e[pre[i]^1].cap += f;
        }
        flow += f;
        cost += f * dis[t];
    }
    return cost;
}
```

